using System.Collections;
using FMODUnity;
using LittleLeo.Variables;
using UnityEngine;

namespace Astrea;

public class ReceiveDiceAnimation : MonoBehaviour
{
	[Header("Animation")]
	[SerializeField]
	private float movementDuration;

	[SerializeField]
	private AnimationCurve movementCurve;

	[SerializeField]
	private AnimationCurve movementCurveDicePool;

	[SerializeField]
	private AnimationCurve movementCurveDicePoolLeftDice;

	[SerializeField]
	private AnimationCurve heightCurve;

	[SerializeField]
	private float height;

	[SerializeField]
	private float heightDicePool;

	[SerializeField]
	private float heightDicePoolLeftDice;

	[SerializeField]
	private AnimationCurve scaleCurve;

	[SerializeField]
	private float scaleDuration;

	[SerializeField]
	private float startScallingDelay;

	[SerializeField]
	private TransformReference discardPoolButtonTransformReference;

	[SerializeField]
	private TransformReference diceBagButtonTransformReference;

	[SerializeField]
	private TransformReference dicePoolButtonTransformReference;

	[SerializeField]
	private FloatReference diceRollingZPosition;

	[SerializeField]
	private DiceVisuals diceVisuals;

	[Header("SFX")]
	[SerializeField]
	private EventReference uiDeckShuffleIn;

	[SerializeField]
	private EventReference commonGainDiceSFX;

	private Dice dice;

	private BagEnum bagEnum;

	private PlayerDiceInventoryData playerDiceInventoryData;

	private int amount;

	public FloatReference DiceRollingZPosition => diceRollingZPosition;

	public DiceVisuals DiceVisuals => diceVisuals;

	public void Initialize(BagEnum bagEnum, Dice dice, PlayerDiceInventoryData playerDiceInventoryData, int amount = 1, bool epic = false, CompendiumItemState compendiumItemState = CompendiumItemState.Discovered)
	{
		this.dice = dice;
		this.bagEnum = bagEnum;
		this.playerDiceInventoryData = playerDiceInventoryData;
		this.amount = amount;
		diceVisuals.InitializeAsDicePreview(dice, mainCamera: true, compendiumItemState);
	}

	public void StartAnimation(bool reshuffling = false)
	{
		StartCoroutine(ReceivingDiceAnimation(reshuffling));
	}

	private IEnumerator ReceivingDiceAnimation(bool reshuffling = false)
	{
		yield return InvokeAlternatives.WaitOneFrame();
		Vector3 startPosition = base.transform.position;
		float num = 0.35f;
		float y = 0.15f;
		Vector3 targetPosition;
		if (bagEnum == BagEnum.DrawPool)
		{
			targetPosition = diceBagButtonTransformReference.value.position.ZeroZ() + new Vector3(num, y, diceRollingZPosition.Value);
		}
		else if (bagEnum == BagEnum.Discard)
		{
			targetPosition = discardPoolButtonTransformReference.value.position.ZeroZ() + new Vector3(0f - num, y, diceRollingZPosition.Value);
		}
		else
		{
			targetPosition = dicePoolButtonTransformReference.value.position.ZeroZ() + new Vector3(0f, 0f, diceRollingZPosition.Value);
			if (dice.DiceTier.EnableCustomGainDiceSFX)
			{
				ReferenceSingleton<SFXHandler>.Instance.PlaySFX(dice.DiceTier.GainDiceSFX);
			}
			else
			{
				ReferenceSingleton<SFXHandler>.Instance.PlaySFX(commonGainDiceSFX);
			}
		}
		Vector3 heightDirection;
		AnimationCurve curve;
		float heightToUse;
		if (bagEnum == BagEnum.DicePool)
		{
			if (base.transform.position.x < -0.5f)
			{
				heightDirection = Vector3.down;
				curve = movementCurveDicePoolLeftDice;
				heightToUse = heightDicePoolLeftDice;
			}
			else
			{
				heightDirection = Vector3.left;
				curve = movementCurveDicePool;
				heightToUse = heightDicePool;
			}
		}
		else
		{
			heightDirection = Vector3.up;
			curve = movementCurve;
			heightToUse = height;
		}
		StartCoroutine(CoroutineUtility.CurveRoutine(movementDuration, curve, delegate(float t, float v)
		{
			base.transform.position = Vector3.LerpUnclamped(startPosition, targetPosition, v) + heightDirection * heightToUse * heightCurve.Evaluate(t);
		}, delegate
		{
			if (!reshuffling)
			{
				playerDiceInventoryData.UpdateDicePoolText();
			}
			diceVisuals.StoreDiceTrailParticles();
			diceVisuals.StoreDiceModel();
			ReferenceSingleton<PoolHandler>.Instance.StoreObject(base.gameObject);
			if (bagEnum != 0)
			{
				ReferenceSingleton<SFXHandler>.Instance.PlaySFX(uiDeckShuffleIn);
			}
		}));
		InvokeAlternatives.Invoke(this, movementDuration - 0.1f, delegate
		{
			diceVisuals.StopGlowParticle();
		});
		yield return new WaitForSeconds(startScallingDelay);
		StartCoroutine(CoroutineUtility.CurveRoutine(scaleDuration, scaleCurve, delegate(float t, float v)
		{
			Vector3 localScale = diceVisuals.transform.localScale;
			diceVisuals.transform.localScale = Vector3.Lerp(localScale, Vector3.zero, v);
		}));
	}

	public void StoreWithNoAnimation()
	{
		diceVisuals.StoreDicePreview();
	}
}
